      Ltac seg_in MI PSI :=
        destruct (seg_hyps _ _ _ _ _ MI PSI) as (PCTX & (sc & u1w & u2w & PCL) & PTT & PINB & PSHB & PTSH & PSZ & INV & (j40 & j16 & FR) & [buf BUF]).
      Ltac splits Hx := nd_splits Hx.   (* [comment removed for export] *)
      (* [comment removed for export] *)
      Ltac seg_leaves :=
        let LV := fresh "LV" in let msF' := fresh "msF'" in let mo' := fresh "mo'" in let AK' := fresh "AK'" in let MP' := fresh "MP'" in
        let pc' := fresh "pc'" in let r' := fresh "r'" in let m' := fresh "m'" in let E' := fresh "E'" in
        intros msF' mo' AK' MP' (pc' & r' & m' & E' & LV);
        repeat (lazymatch type of LV with _ \/ _ => destruct LV as [LV|LV] end); splits LV; subst pc'; try subst m'.
      Ltac cut_prep MI PSI := uprep; seg_in MI PSI; pose proof PSI as (PE & PD & PEC & PM & PIT & PT & PCH & TNN).
