      Ltac clear_ors := repeat match goal with H : _ \/ _ |- _ => clear H end.
      Ltac olia := first [ assumption | (clear_ors; Zify.zify; xlia zchecker) | (Zify.zify; xlia zchecker) ].
      (* [comment removed for export] *)
      Ltac reg_chain := first [ eassumption | etransitivity; [eassumption|]; first [ eassumption | etransitivity; [eassumption|]; first [ eassumption | etransitivity; [eassumption|]; eassumption ] ] ].
      (* [comment removed for export] *)
      Ltac lit_eq := lazymatch goal with |- Z_to_bv _ _ = Z_to_bv _ _ => first [ apply bv_eq; rewrite !Z_to_bv_unsigned; reflexivity | f_equal; lia ] end.
      Ltac zbv := symmetry; apply Z_to_bv_bv_unsigned.
      Ltac reg_step := match goal with |- ?f ?rr = _ => match goal with E : f rr = _ |- _ => rewrite E end end.
      Ltac regeq_n n := first [ reflexivity
                              | lazymatch n with O => fail | S ?k => reg_step; regeq_n k end
                              | zbv | lit_eq | eassumption ].
      Ltac regeq := regeq_n 5%nat.
      Ltac pcore := unfold pecore; repeat apply conj; regeq.
      Ltac a8tot := try (lazymatch goal with A : a8I _ _ _ _ _ |- _ => pose proof A as (_ & _ & _ & ?T0 & _) end).
      Ltac arith_goal := lazymatch goal with
                         | |- (_ <= _ <= _)%Z => idtac | |- (_ <= _ < _)%Z => idtac | |- (_ < _ <= _)%Z => idtac | |- (_ < _ < _)%Z => idtac
                         | |- (_ <= _)%Z => idtac | |- (_ < _)%Z => idtac | |- (_ >= _)%Z => idtac | |- (_ > _)%Z => idtac
                         | |- @eq Z _ _ => idtac | |- not (@eq Z _ _) => idtac | |- _ \/ _ => idtac end.
      (* [comment removed for export] *)
      Ltac kx := first [ lazymatch goal with |- pecore ?rr _ _ _ _ => first [ match goal with P : pecore rr _ _ _ _ |- _ => exact P end | pcore ] end
                        | eassumption
                        | zbv
                        | regeq
                        | lazymatch goal with |- _ <= bv_unsigned (?f ?rr) <= _ =>
                            first [ match goal with E : f rr = _ |- _ => rewrite E end; first [ assumption | rewrite unsigned_lit by lia; lia ]
